import base64,json,pathlib,subprocess,sys
root=pathlib.Path(__file__).resolve().parent;backup_root=pathlib.Path('/opt/openg2p-lab/backups/geo-import');backup_root.mkdir(parents=True,exist_ok=True,mode=0o700);data=json.loads((root/'nigeria_ocha_lga.json').read_text());payload=base64.b64encode(json.dumps(data).encode()).decode(); apply='--apply' in sys.argv
script='''import asyncio,asyncpg,os,json,base64,collections,re\nDATA=json.loads(base64.b64decode(PAYLOAD)); APPLY=DO_APPLY\ndef norm(x): return re.sub(r"[^a-z0-9]", "",x.lower()).replace("nassarawa","nasarawa")\nasync def main():\n p="MASTER_DATA_API_DB_";c=await asyncpg.connect(host=os.environ[p+"HOSTNAME"],port=int(os.environ[p+"PORT"]),database=os.environ[p+"DBNAME"],user=os.environ[p+"USERNAME"],password=os.environ[p+"PASSWORD"])\n async with c.transaction():\n  await c.execute("LOCK TABLE g2p_geo_level_values IN SHARE ROW EXCLUSIVE MODE")\n  rows=[dict(x) for x in await c.fetch("SELECT level_value_id,level_id,level_value_mnemonic,parent_level_value_id FROM g2p_geo_level_values ORDER BY level_id,level_value_id")]\n  states={norm(x["level_value_mnemonic"]):x["level_value_id"] for x in rows if x["level_id"]=="state"}\n  assert len(states)==37 and len(DATA)==774 and len(set(x["pcode"] for x in DATA))==774\n  assert set(states)=={norm(x["state"]) for x in DATA}\n  existing={}\n  for x in rows:\n   if x["level_id"]=="lga":\n    k=(x["parent_level_value_id"],norm(x["level_value_mnemonic"]));assert k not in existing;existing[k]=x\n  new=[];matched=[];allids={x["level_value_id"] for x in rows};seen=set()\n  for x in DATA:\n   parent=states[norm(x["state"])];k=(parent,norm(x["name"]));assert k not in seen;seen.add(k)\n   if k in existing: matched.append((x,existing[k]));continue\n   ident="OCHA-"+x["pcode"];assert ident not in allids;new.append((ident,"lga",x["name"],parent))\n  assert len(matched)==len(existing) and len(new)+len(matched)==774\n  print(json.dumps({"backup":rows,"insert_count":len(new),"matched_count":len(matched),"matched":[{"source":a,"existing":b} for a,b in matched],"counts":dict(collections.Counter(x["state"] for x in DATA)),"applied":APPLY}))\n  if APPLY: await c.executemany("INSERT INTO g2p_geo_level_values(level_value_id,level_id,level_value_mnemonic,parent_level_value_id) VALUES($1,$2,$3,$4)",new)\n  count=await c.fetchval("SELECT count(*) FROM g2p_geo_level_values WHERE level_id='lga'");assert count==(774 if APPLY else len(existing))\n await c.close()\nasyncio.run(main())\n'''.replace('PAYLOAD',repr(payload)).replace('DO_APPLY',repr(apply))
r=subprocess.run(['kubectl','-n','nigeria','exec','-i','deploy/commons-services-master-data-api','--','python','-'],input=script,text=True,capture_output=True,check=True);result=json.loads(r.stdout)
if not apply:
 f=backup_root/'master-geo-before-ocha-import.json'; f.write_text(json.dumps(result['backup'],indent=2),encoding='utf-8'); f.chmod(0o600)
else:
 f=backup_root/'master-geo-ocha-import-report.json'; f.write_text(json.dumps({k:v for k,v in result.items() if k!='backup'},indent=2),encoding='utf-8'); f.chmod(0o600)
print(json.dumps({k:v for k,v in result.items() if k not in ('backup','counts')},indent=2))
